"use strict";
const PLAN={step:1,college:"",major:"",targetIds:new Set(),statuses:{},view:"onboarding",query:"",campusQuery:"",agreementStage:0,editing:false,scenario:"custom",baseline:null};
const COLLEGES=[{id:"district",name:"San Diego Community College District",city:"San Diego, CA"},{id:"city",name:"San Diego City College",city:"San Diego, CA"},{id:"mesa",name:"San Diego Mesa College",city:"San Diego, CA"},{id:"miramar",name:"San Diego Miramar College",city:"San Diego, CA"},{id:"continuing",name:"San Diego College of Continuing Education",city:"San Diego, CA"}];
const CAMPUSES=[{"id":"ucb","name":"UC Berkeley","system":"UC","city":"Berkeley, CA"},{"id":"ucd","name":"UC Davis","system":"UC","city":"Davis, CA"},{"id":"uci","name":"UC Irvine","system":"UC","city":"Irvine, CA"},{"id":"ucla","name":"UCLA","system":"UC","city":"Los Angeles, CA"},{"id":"ucm","name":"UC Merced","system":"UC","city":"Merced, CA"},{"id":"ucr","name":"UC Riverside","system":"UC","city":"Riverside, CA"},{"id":"ucsd","name":"UC San Diego","system":"UC","city":"La Jolla, CA"},{"id":"ucsb","name":"UC Santa Barbara","system":"UC","city":"Santa Barbara, CA"},{"id":"ucsc","name":"UC Santa Cruz","system":"UC","city":"Santa Cruz, CA"},{"id":"bakersfield","name":"CSU Bakersfield","system":"CSU","city":"Bakersfield, CA"},{"id":"channelislands","name":"CSU Channel Islands","system":"CSU","city":"Camarillo, CA"},{"id":"chico","name":"Chico State","system":"CSU","city":"Chico, CA"},{"id":"dominguez","name":"CSU Dominguez Hills","system":"CSU","city":"Carson, CA"},{"id":"eastbay","name":"CSU East Bay","system":"CSU","city":"Hayward, CA"},{"id":"fresno","name":"Fresno State","system":"CSU","city":"Fresno, CA"},{"id":"fullerton","name":"CSU Fullerton","system":"CSU","city":"Fullerton, CA"},{"id":"humboldt","name":"Cal Poly Humboldt","system":"CSU","city":"Arcata, CA"},{"id":"longbeach","name":"CSU Long Beach","system":"CSU","city":"Long Beach, CA"},{"id":"losangeles","name":"Cal State Los Angeles","system":"CSU","city":"Los Angeles, CA"},{"id":"monterey","name":"CSU Monterey Bay","system":"CSU","city":"Seaside, CA"},{"id":"northridge","name":"CSU Northridge","system":"CSU","city":"Northridge, CA"},{"id":"pomona","name":"Cal Poly Pomona","system":"CSU","city":"Pomona, CA"},{"id":"sacramento","name":"Sacramento State","system":"CSU","city":"Sacramento, CA"},{"id":"sanbernardino","name":"CSU San Bernardino","system":"CSU","city":"San Bernardino, CA"},{"id":"sdsu","name":"San Diego State","system":"CSU","city":"San Diego, CA"},{"id":"sfsu","name":"San Francisco State","system":"CSU","city":"San Francisco, CA"},{"id":"sjsu","name":"San José State","system":"CSU","city":"San José, CA"},{"id":"slo","name":"Cal Poly San Luis Obispo","system":"CSU","city":"San Luis Obispo, CA"},{"id":"csusm","name":"CSU San Marcos","system":"CSU","city":"San Marcos, CA"},{"id":"sonoma","name":"Sonoma State","system":"CSU","city":"Rohnert Park, CA"},{"id":"stanislaus","name":"Stanislaus State","system":"CSU","city":"Turlock, CA"}];
const MAJORS=["Computer Science","Computer Engineering","Mathematics","Engineering","Business Administration","Biology","Psychology","Economics","Undecided"];
const STATUS_LABELS={none:"Not added",completed:"Completed",registered:"Registered",planning:"Planning"};
const escapeHTML=value=>String(value??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const collegeName=()=>COLLEGES.find(c=>c.id===PLAN.college)?.name||"SDCCD";
const chosenCampuses=()=>CAMPUSES.filter(c=>PLAN.targetIds.has(c.id));
const statusOf=id=>PLAN.statuses[id]||"none";
const selectedRecords=()=>activeCourses().filter(c=>statusOf(c.id)!=="none");
const normalizeMajor=value=>String(value??"").toLowerCase().replace(/\b(b\.?[as]\.?|bs|ba|degree|major)\b/g," ").replace(/[^a-z]+/g," ").trim();
const CS_ALIASES=["computer science","comp sci","compsci","cs"];
const isCS=()=>{const m=normalizeMajor(PLAN.major);return CS_ALIASES.includes(m)};
function selectionCounts(){const r={completed:0,registered:0,planning:0,units:0};for(const c of selectedRecords()){r[statusOf(c.id)]++;r.units+=c.units}return r}
function statusOptions(id){return Object.entries(STATUS_LABELS).map(([v,label])=>'<option value="'+v+'" '+(statusOf(id)===v?"selected":"")+'>'+label+'</option>').join("")}
function wizardFrame(body){document.getElementById("onboarding").innerHTML='<header class="onboard-header"><a class="brand" href="#"><span class="brand-mark">↗</span><span>transfer<span class="brand-light">copilot</span></span></a><div><span class="demo-tag">SAN DIEGO PILOT</span>'+(PLAN.editing?'<button class="button subtle" data-wizard-action="cancel-edit">Return to my plan</button>':'')+'</div></header><div class="workflow-shell"><main id="onboarding-main" class="onboard-main" tabindex="-1"><div class="eyebrow">STEP '+String(PLAN.step).padStart(2,"0")+' / 04</div>'+body+'</main><p class="workflow-disclaimer">A planning demo, not academic advice. Official facts and demo assumptions stay separate.</p></div>'}
function reviewFrame(body){document.getElementById("onboarding").innerHTML='<header class="onboard-header"><a class="brand" href="#"><span class="brand-mark">↗</span><span>transfer<span class="brand-light">copilot</span></span></a><div><span class="demo-tag">SAN DIEGO PILOT</span><button class="button subtle" type="button" data-review-dashboard>Return to my plan</button></div></header><div class="review-shell"><main id="onboarding-main" class="onboard-main" tabindex="-1"><div class="eyebrow">REVIEW &amp; EXPORT</div>'+body+'</main><p class="workflow-disclaimer">Exports are generated in your browser. Nothing is uploaded by this demo.</p></div>'}
function nextActions(label){return '<div id="wizard-error" role="alert"></div><div class="wizard-actions"><button class="button subtle" type="button" data-wizard-action="back">← Back</button><button class="button navy" type="submit">'+label+' <span>→</span></button></div>'}
function renderOnboarding(focus=false){document.body.dataset.view="onboarding";document.querySelector(".skip").href="#onboarding-main";
if(PLAN.step===1)wizardFrame('<form id="profile-form"><fieldset class="college-picker"><legend class="field-label">Current college</legend><div class="college-options">'+COLLEGES.map(c=>'<label class="school-tile"><input class="tile-input" type="radio" name="home-college" value="'+c.id+'" '+(PLAN.college===c.id?'checked':'')+' required>'+schoolBadge(c.id)+'<span class="school-tile-name">'+c.name+'</span><span class="school-tile-city">'+c.city+'</span><span class="tile-check" aria-hidden="true">✓</span></label>').join("")+'</div></fieldset><p class="field-help">Only SDCCD and its colleges are included. Noncredit Continuing Education courses are not evaluated in this credit-transfer demo.</p><div class="privacy-note"><span>◈</span><p><strong>Your information stays in this tab.</strong> We do not send your answers to a server or retain them after refresh. No name or account needed.</p></div><div id="wizard-error" role="alert"></div><div class="wizard-actions"><span>About 2 minutes</span><button class="button navy" type="submit">Choose my destinations →</button></div></form>');
if(PLAN.step===2){wizardFrame('<form id="targets-form"><div class="campus-search-row"><label class="search-field"><span aria-hidden="true">⌕</span><input type="search" id="campus-search" placeholder="Search a campus" aria-label="Search UC and CSU campuses" value="'+escapeHTML(PLAN.campusQuery)+'"></label><span id="campus-selected-count"></span></div><div class="selected-campus-chips" id="selected-campus-chips"></div><div id="campus-picker"></div><p class="field-help">Campuses marked <em class="coverage-flag inline-flag">ASSIST CS snapshot</em> have a source-linked Computer Science agreement in this demo; every other campus-major match is illustrative or unverified. UC San Francisco is graduate-only and is not an undergraduate transfer option. CSU’s current directory lists 22 universities.</p><p class="directory-links"><a href="https://www.universityofcalifornia.edu/about-uc/campuses-locations" target="_blank" rel="noopener noreferrer">UC directory ↗</a><a href="https://www.calstate.edu/attend/campuses" target="_blank" rel="noopener noreferrer">CSU directory ↗</a></p>'+nextActions("Choose my major")+'</form>');renderCampusPicker()}
if(PLAN.step===3)wizardFrame('<form id="major-form"><label class="field-label" for="intended-major">Intended major</label><input id="intended-major" class="field-input" list="major-options" maxlength="100" placeholder="e.g. Computer Science" value="'+escapeHTML(PLAN.major)+'" required><datalist id="major-options">'+MAJORS.map(m=>'<option value="'+m+'"></option>').join("")+'</datalist><div class="major-examples" aria-label="Popular majors">'+MAJORS.slice(0,6).map(m=>'<button class="major-tile '+(PLAN.major===m?'selected':'')+'" type="button" data-major-choice="'+m+'" aria-pressed="'+(PLAN.major===m)+'"><span class="major-mark" aria-hidden="true">'+m.split(" ").map(word=>word[0]).join("").slice(0,2)+'</span><strong>'+m+'</strong><span class="tile-check" aria-hidden="true">✓</span></button>').join("")+'</div><div class="privacy-note"><span>i</span><p><strong>Computer Science has the richest demo.</strong> Other majors work through the full flow, but major-specific matches may be unavailable. Selecting a major does not confirm that every chosen campus offers it.</p></div>'+nextActions("Add my coursework")+'</form>');
if(PLAN.step===4){const agreement=activeAssistAgreement();wizardFrame('<form id="courses-form">'+courseScopeHTML()+(agreement?agreementJourneyHTML(agreement):'<label class="search-field wizard-course-search"><span aria-hidden="true">⌕</span><input type="search" id="wizard-course-search" placeholder="Search course code or title" aria-label="Search coursework" value="'+escapeHTML(PLAN.query)+'"></label>')+'<div class="status-legend"><span><i class="status-dot completed"></i>Completed</span><span><i class="status-dot registered"></i>Registered</span><span><i class="status-dot planning"></i>Planning</span></div><div id="wizard-course-list"></div><div id="course-selection-summary" class="selection-summary" role="status"></div><p class="directory-links"><a href="https://www.sdccd.edu/students/college-catalogs/" target="_blank" rel="noopener noreferrer">All SDCCD catalogs ↗</a><a href="'+SOURCES.classSearch+'" target="_blank" rel="noopener noreferrer">Official class search ↗</a></p>'+(agreement&&PLAN.agreementStage<agreementStages(agreement).length-1?'':'<label class="empty-history"><input type="checkbox" id="no-coursework"> I haven’t added any coursework yet—start with an empty plan.</label>')+'<p class="field-help">Select a Miramar course to mark it Completed, Registered or Planning. Registered and planned work stay visible but never count as completed.</p>'+courseworkActions(agreement)+'</form>');OPEN_COURSE="";renderWizardCourses()}
if(focus){document.getElementById("onboarding-main").focus({preventScroll:true});window.scrollTo({top:0,behavior:"auto"})}}
function renderCampusPicker(){const q=PLAN.campusQuery.trim().toLowerCase();document.getElementById("campus-picker").innerHTML=["UC","CSU"].map(system=>{const list=CAMPUSES.filter(c=>c.system===system&&(!q||c.name.toLowerCase().includes(q)||c.id.includes(q)||c.city.toLowerCase().includes(q)));return'<fieldset class="campus-group"><legend>'+system+' <span>'+ (system==="UC"?"University of California":"California State University")+'</span></legend><div class="campus-options">'+list.map(c=>'<label class="school-tile '+(PLAN.targetIds.has(c.id)?"checked":"")+'"><input class="tile-input" type="checkbox" value="'+c.id+'" data-wizard-campus="'+c.id+'" '+(PLAN.targetIds.has(c.id)?"checked":"")+'>'+schoolBadge(c.id)+'<span class="school-tile-name">'+c.name+'</span><span class="school-tile-city">'+c.city+'</span>'+((PLAN.college==="miramar"?MIRAMAR_CS_AGREEMENTS:ASSIST_AGREEMENTS)[c.id]?'<em class="coverage-flag">ASSIST CS snapshot</em>':'')+'<span class="tile-check" aria-hidden="true">✓</span></label>').join("")+'</div>'+(list.length?"":'<p class="field-help">No matching '+system+' campus.</p>')+'</fieldset>'}).join("");document.getElementById("campus-selected-count").textContent=PLAN.targetIds.size+" selected";document.getElementById("selected-campus-chips").innerHTML=chosenCampuses().map(c=>'<button type="button" class="selected-chip" data-remove-campus="'+c.id+'" aria-label="Remove '+c.name+'">'+schoolBadge(c.id)+c.name+' <span>×</span></button>').join("")}
function courseScopeHTML(){const list=activeAssistAgreements();if(!list.length)return '<div class="catalog-scope"><strong>SDCCD starter catalog · Mesa examples</strong><p>These 7 catalog-backed examples are at San Diego Mesa College. Choose Miramar, Computer Science and UC Berkeley, UCLA or Cal Poly San Luis Obispo to see complete source-driven agreements.</p></div>';const missing=chosenCampuses().filter(t=>!MIRAMAR_CS_AGREEMENTS[t.id]);return '<div class="catalog-scope assist-scope"><span class="scope-kicker">OFFICIAL AGREEMENT WALKTHROUGH</span><strong class="school-inline">'+schoolBadge("miramar")+'San Diego Miramar College <span aria-hidden="true">→</span> '+list.map(a=>schoolBadge(a.targetId)+a.receiving).join(" · ")+'</strong><p>Computer Science · '+list[0].year+'. Each section mirrors its ASSIST agreement. Mark a Miramar course once and every school that uses it updates.'+(missing.length?' No agreement in this demo for '+missing.map(t=>t.name).join(", ")+'.':'')+'</p><p class="directory-links">'+list.map(a=>'<a href="'+a.source+'" target="_blank" rel="noopener noreferrer">'+a.receiving+' agreement on ASSIST ↗</a>').join("")+'</p></div>'}
function agreementStages(){return activeAssistAgreements().flatMap(a=>a.sections.flatMap(section=>section.groups.map((group,index)=>({a,section,group,label:a.shortName+" · "+(group.label?"Group "+group.label:section.stageTitle||section.title),short:group.instruction||((group.rule==="all"?"Complete all":group.rule==="one"?"Choose one":"Choose "+group.minUnits+" units")+" · "+group.items.length+" option"+(group.items.length===1?"":"s")),firstInSection:index===0}))))}
function agreementJourneyHTML(a){const stages=agreementStages(a);return '<nav class="agreement-journey" aria-label="ASSIST agreement workflow"><ol>'+stages.map((s,i)=>'<li class="'+(i===PLAN.agreementStage?'current':i<PLAN.agreementStage?'visited':'upcoming')+'"><button type="button" data-agreement-stage="'+i+'" '+(i===PLAN.agreementStage?'aria-current="step"':'')+'><span>'+(i+1)+'</span><strong>'+s.label+'</strong><small>'+s.short+'</small></button></li>').join("")+'</ol></nav>'}
function courseworkActions(a){if(!a)return nextActions("See my transfer plan");const stages=agreementStages(a),last=stages.length-1,back=PLAN.agreementStage?'<button class="button subtle" type="button" data-agreement-back>← Previous group</button>':'<button class="button subtle" type="button" data-wizard-action="back">← Back to major</button>';return '<div id="wizard-error" role="alert"></div><div class="wizard-actions agreement-actions">'+back+(PLAN.agreementStage<last?'<button class="button navy" type="button" data-agreement-next>Continue to '+stages[PLAN.agreementStage+1].label+' <span>→</span></button>':'<button class="button navy" type="submit">See my transfer plan <span>→</span></button>')+'</div>'}
let OPEN_COURSE="",OPEN_TILE=null;
function courseStatusLabel(s){return s==="none"?"Choose status":STATUS_LABELS[s]}
function wizardCourseRow(c,mapLabel="",key=""){const s=statusOf(c.id),open=OPEN_COURSE===c.id;return '<div class="course-tile status-'+s+(open?' open':'')+'" data-course-tile="'+c.id+'"><button type="button" class="course-pick" data-course-toggle="'+c.id+'" aria-expanded="'+open+'" aria-controls="status-drawer-'+c.id+(key?'-'+key:'')+'"><span class="course-pick-text">'+(mapLabel?'<span class="map-side-label course-side-label">'+mapLabel+'</span>':'')+'<strong>'+c.code+'</strong><span>'+c.title+'</span><small class="school-inline">'+schoolBadge(c.schoolId||"mesa")+(c.schoolId==="miramar"?"Miramar":"Mesa")+' · '+c.units+' units · '+c.catalogYear+'</small></span><span class="course-status-label">'+courseStatusLabel(s)+'</span></button><div class="status-drawer" id="status-drawer-'+c.id+(key?'-'+key:'')+'" role="group" aria-label="Status for '+c.code+'">'+["completed","registered","planning"].map(k=>'<button type="button" class="status-option '+k+'" data-set-status="'+k+'" data-course-id="'+c.id+'" aria-pressed="'+(s===k)+'">'+STATUS_LABELS[k]+'</button>').join("")+'<button type="button" class="status-option clear" data-set-status="none" data-course-id="'+c.id+'" aria-label="Remove status for '+c.code+'" title="Remove status">×</button></div></div>'}
function courseTile(id){return document.querySelector('[data-course-tile="'+id+'"]')}
function closeCourseDrawer(){const t=OPEN_TILE||(OPEN_COURSE&&courseTile(OPEN_COURSE));if(t&&t.isConnected){t.classList.remove("open");t.querySelector(".course-pick").setAttribute("aria-expanded","false")}OPEN_COURSE="";OPEN_TILE=null}
function openCourseDrawer(id,tile){closeCourseDrawer();const t=tile||courseTile(id);if(!t)return;OPEN_COURSE=id;OPEN_TILE=t;t.classList.add("open");t.querySelector(".course-pick").setAttribute("aria-expanded","true");(t.querySelector('.status-option[aria-pressed="true"]')||t.querySelector(".status-option")).focus({preventScroll:true})}
function paintCourseTile(id){const s=statusOf(id);document.querySelectorAll('[data-course-tile="'+id+'"]').forEach(t=>{t.className=t.className.replace(/status-\w+/,"status-"+s);t.querySelector(".course-status-label").textContent=courseStatusLabel(s);t.querySelectorAll("[data-set-status]").forEach(b=>b.setAttribute("aria-pressed",String(b.dataset.setStatus===s)))})}
function applyCourseStatus(id,status){if(!Object.hasOwn(STATUS_LABELS,status))return;const origin=OPEN_TILE,agreements=activeAssistAgreements(),changed=[id];PLAN.statuses[id]=status;if(status!=="none")for(const a of agreements)for(const s of a.sections)for(const g of s.groups){if(g.rule!=="one")continue;const chosen=g.items.filter(i=>i.courseIds.includes(id));if(!chosen.length)continue;const keep=new Set(chosen.flatMap(i=>i.courseIds));for(const i of g.items)if(!chosen.includes(i))for(const other of i.courseIds)if(!keep.has(other)&&statusOf(other)!=="none"&&!courseUsedOutsideGroup(other,g,agreements)){PLAN.statuses[other]="none";changed.push(other)}}if(PLAN.view==="dashboard"){closeCourseDrawer();PLAN.scenario="custom";render();return}changed.forEach(paintCourseTile);refreshAgreementStates();closeCourseDrawer();(origin&&origin.isConnected?origin:courseTile(id))?.querySelector(".course-pick").focus({preventScroll:true});updateSelectionSummary()}
// A "choose one" pick only clears other options whose courses no other requirement or school still uses.
function courseUsedOutsideGroup(id,group,agreements){return agreements.some(a=>a.sections.some(s=>s.groups.some(g=>g!==group&&g.items.some(i=>i.courseIds.includes(id)))))}
const OK_STATES=["Completed","In your plan"];
function itemState(item){if(item.alternateListing)return "Alternate listing";if(!itemBundles(item).length)return item.atUniversity?"At university":"No Miramar course";const level=itemLevel(item);if(level==="completed")return "Completed";if(level!=="none")return "In your plan";const added=item.courseIds.filter(id=>statusOf(id)!=="none").length;return added?added+" of "+item.courseIds.length+" selected":"Not started"}
function groupState(g){const items=g.items.filter(i=>!i.alternateListing);if(!items.some(i=>itemBundles(i).length))return "No Miramar course";const levels=groupLevels(g);if(g.rule!=="all"){const l=levels[0];return l==="completed"?"Completed":l!=="none"?"In your plan":g.rule==="units"?"Select "+g.minUnits+" units":"Choose 1"}if(levels.every(l=>l==="completed"))return "Completed";if(levels.every(l=>l!=="none"))return "In your plan";const ok=levels.filter(l=>l!=="none").length;return ok?ok+" of "+levels.length+" in your plan":"Not started"}
function agreementDecisions(a){return agreementDecisionLevels(a).map(l=>l!=="none")}
function refreshAgreementStates(){for(const a of activeAssistAgreements())for(const s of a.sections)for(const g of s.groups){document.querySelectorAll('[data-group="'+g.id+'"] .group-state').forEach(e=>{e.textContent=groupState(g)});for(const item of g.items)document.querySelectorAll('[data-requirement="'+item.id+'"] .item-state').forEach(e=>{e.textContent=itemState(item)})}}
function agreementItemHTML(a,item){const bundles=item.options||(item.courseIds.length?[item.courseIds]:[]),bundleHTML=b=>b.map(courseById).filter(Boolean).map((c,i)=>(i?'<div class="logic-divider and">and</div>':'')+'<div class="mapped-course-option">'+(item.acceptedCourseIds?'<span class="course-role '+(item.acceptedCourseIds.includes(c.id)?'accepted':'published-pair')+'">'+(item.acceptedCourseIds.includes(c.id)?'Accepted for Computer Science':'Published pair · not required for CS')+'</span>':'')+wizardCourseRow(c,"MIRAMAR COURSE",item.id)+'</div>').join(""),left=bundles.length?bundles.map((b,i)=>(i?'<div class="logic-divider or">or</div>':'')+bundleHTML(b)).join(""):'<div class="no-articulation"><span class="map-side-label">MIRAMAR COURSE</span><strong>'+(item.atUniversity?'Not available at Miramar':'No articulated course')+'</strong><p>'+(item.atUniversity||item.noArticulation)+'</p></div>';return '<article class="agreement-item'+(item.alternateListing?' alternate-listing':'')+'" data-requirement="'+item.id+'"><div class="articulation-map"><div class="requirement-courses">'+left+'</div><div class="mapping-arrow" aria-label="maps from Miramar to '+a.receiving+'"><span>→</span><small>maps to</small></div><div class="receiving-course"><span class="course-pick-text"><span class="map-side-label course-side-label">'+(item.partLabel?item.partLabel+' · ':'')+a.shortName.toUpperCase()+' EQUIVALENT</span><strong>'+item.receivingCode+'</strong><span>'+item.receivingTitle+'</span><small class="school-inline">'+schoolBadge(a.targetId)+a.receiving+(item.receivingUnits?' · '+item.receivingUnits+(a.quarter?' quarter units':' units'):'')+(item.sameAs?' · Same as '+item.sameAs:'')+'</small></span>'+(bundles.length&&!item.alternateListing?'<span class="requirement-state item-state">'+itemState(item)+'</span>':'')+'</div></div>'+(item.alternateListing?'<p class="agreement-note alternate"><strong>Alternate listing:</strong> '+item.alternateListing+' Not counted separately.</p>':'')+(item.note?'<p class="agreement-note"><strong>Agreement note:</strong> '+item.note+'</p>':'')+nearbyOptionsHTML(a,item)+'</article>'}
function nearbyOptionsHTML(a,item){if(a.targetId!==NEARBY_UCB_CS.targetId||item.courseIds.length||item.atUniversity||item.alternateListing)return "";const n=NEARBY_UCB_CS,options=n.options[item.id]||[],college=id=>n.checked.find(c=>c.id===id);if(!options.length)return '<details class="nearby-options none"><summary><span><span class="nearby-kicker">OTHER SAN DIEGO-AREA COLLEGES</span><strong>No nearby articulated option found for '+item.receivingCode+'</strong></span><span aria-hidden="true">+</span></summary><div class="nearby-content"><small>Checked the '+n.year+' ASSIST agreements for '+n.checked.map(c=>c.name).join(", ")+'.</small></div></details>';return '<details class="nearby-options"><summary><span><span class="nearby-kicker">OPTION AT ANOTHER COLLEGE</span><strong>'+options.length+' nearby college'+(options.length===1?' has':'s have')+' an articulated path to '+item.receivingCode+'</strong></span><span aria-hidden="true">+</span></summary><div class="nearby-content"><div class="nearby-list">'+options.map(o=>{const c=college(o.college);return '<div class="nearby-option"><div class="nearby-college">'+schoolBadge(c.id)+'<span><strong>'+c.name+'</strong><small>'+c.city+'</small></span></div><div class="nearby-courses">'+o.courses.map((x,i)=>(i?'<span class="nearby-and">and</span>':'')+'<span class="nearby-course"><strong>'+x.code+'</strong> '+x.title+' · '+x.units+' units</span>').join("")+'</div>'+(o.note?'<p class="nearby-note">ASSIST note: '+o.note+'.'+(o.additionalUniversityCourse?' Berkeley’s agreement says this means also taking '+o.additionalUniversityCourse+' after you transfer.':'')+'</p>':'')+'<a href="'+c.source+'" target="_blank" rel="noopener noreferrer">'+c.name+' → UC Berkeley agreement ↗</a></div>'}).join("")+'</div><p class="nearby-caveat">A course set must be completed at that one college. ASSIST doesn’t show whether Miramar accepts these courses, and sections, prerequisites and seats aren’t checked—confirm with a counselor before enrolling. Also checked, no articulated course: '+n.checked.filter(c=>!options.some(o=>o.college===c.id)).map(c=>c.name).join(", ")+'.</p></div></details>'}
function agreementSectionHTML(a,section,g){return '<section class="assist-requirement"><div class="assist-requirement-head"><div><span class="requirement-kind">'+a.receiving+' · '+a.program+'</span><h3>'+section.title+(section.instruction?' — '+section.instruction:'')+'</h3></div><span class="requirement-state">'+(section.counts?'Counts toward Transfer Completion':'Not counted in Transfer Completion')+'</span></div>'+(section===a.sections[0]&&g===section.groups[0]&&a.keyNotes&&a.keyNotes.length?'<ul class="agreement-key-notes">'+a.keyNotes.map(n=>'<li>'+n+'</li>').join("")+'</ul>':'')+'<div class="agreement-group" data-group="'+g.id+'">'+(g.label||g.instruction?'<div class="agreement-group-head">'+(g.label?'<span class="group-letter"><span class="sr-only">Group </span>'+g.label+'</span>':'')+'<div>'+(g.label?'<strong>Group '+g.label+'</strong>':'')+(g.instruction?'<p class="requirement-decision">'+g.instruction+'</p>':'')+'</div>'+(section.counts?'<span class="requirement-state group-state">'+groupState(g)+'</span>':'')+'</div>':'')+g.items.map((item,i)=>(i&&g.rule!=="all"?'<div class="logic-divider or">or</div>':'')+agreementItemHTML(a,item)).join("")+'</div></section>'}
function renderAgreementStage(){const stages=agreementStages(),stage=stages[Math.min(PLAN.agreementStage,stages.length-1)];return stage?agreementSectionHTML(stage.a,stage.section,stage.group):""}
function renderWizardCourses(){const q=PLAN.query.trim().toLowerCase(),a=activeAssistAgreement();if(a)document.getElementById("wizard-course-list").innerHTML=renderAgreementStage(a);else{const list=activeCourses().filter(c=>(c.code+" "+c.title).toLowerCase().includes(q));document.getElementById("wizard-course-list").innerHTML=list.length?list.map(wizardCourseRow).join(""):'<div class="empty-state"><h3>No courses match this sample.</h3><p>Try a different search or use the official catalog links below.</p></div>'}updateSelectionSummary()}
function updateSelectionSummary(){const s=selectionCounts(),list=activeAssistAgreements();const prefix=list.length?"Counted requirements in your plan: "+list.map(a=>{const d=agreementDecisions(a);return a.shortName+" "+d.filter(Boolean).length+"/"+d.length}).join(" · ")+" · ":"";document.getElementById("course-selection-summary").textContent=prefix+s.completed+" completed · "+s.registered+" registered · "+s.planning+" planning";const empty=document.getElementById("no-coursework");if(!empty)return;if(selectedRecords().length){empty.checked=false;empty.disabled=true}else empty.disabled=false}
function wizardError(message){const el=document.getElementById("wizard-error");el.className="field-error";el.textContent=message;el.scrollIntoView({block:"nearest"})}
function showDashboard(){PLAN.view="dashboard";document.body.dataset.view="dashboard";document.querySelector(".skip").href="#main";if(!PLAN.baseline)PLAN.baseline={...PLAN.statuses};render();window.scrollTo({top:0,behavior:"auto"});document.querySelector("#main h1").setAttribute("tabindex","-1");document.querySelector("#main h1").focus({preventScroll:true})}
function beginReviewExport(){PLAN.view="export";document.body.dataset.view="export";document.querySelector(".skip").href="#onboarding-main";reviewFrame(reviewExportHTML());document.getElementById("onboarding-main").focus({preventScroll:true});window.scrollTo({top:0,behavior:"auto"})}
function beginEdit(step=1){PLAN.editSnapshot={college:PLAN.college,major:PLAN.major,targetIds:[...PLAN.targetIds],statuses:{...PLAN.statuses}};PLAN.editing=true;PLAN.step=step;PLAN.query="";PLAN.campusQuery="";PLAN.agreementStage=0;renderOnboarding(true)}
function startOver(){PLAN.step=1;PLAN.college="";PLAN.major="";PLAN.targetIds=new Set();PLAN.statuses={};PLAN.baseline=null;PLAN.query="";PLAN.campusQuery="";PLAN.agreementStage=0;PLAN.editing=false;PLAN.view="onboarding";delete PLAN.editSnapshot;renderOnboarding(true)}
document.addEventListener("submit",event=>{const id=event.target.id;if(!["profile-form","targets-form","major-form","courses-form"].includes(id))return;event.preventDefault();
if(id==="profile-form"){const college=document.querySelector('input[name="home-college"]:checked')?.value;if(!COLLEGES.some(c=>c.id===college))return wizardError("Choose a college in SDCCD.");PLAN.college=college;PLAN.step=2}
if(id==="targets-form"){if(!PLAN.targetIds.size)return wizardError("Choose at least one UC or CSU campus.");PLAN.step=3}
if(id==="major-form"){const major=document.getElementById("intended-major").value.trim();if(!major)return wizardError("Enter an intended major, or choose Undecided.");PLAN.major=major;PLAN.agreementStage=0;PLAN.step=4}
if(id==="courses-form"){if(!selectedRecords().length&&!document.getElementById("no-coursework").checked)return wizardError("Choose a status for at least one course, or select the empty-plan option.");PLAN.baseline={...PLAN.statuses};PLAN.scenario="custom";PLAN.editing=false;return showDashboard()}
renderOnboarding(true)});
document.addEventListener("input",e=>{if(e.target.id==="campus-search"){PLAN.campusQuery=e.target.value;renderCampusPicker()}if(e.target.id==="intended-major")syncMajorTiles();if(e.target.id==="wizard-course-search"){PLAN.query=e.target.value;renderWizardCourses()}});
document.addEventListener("change",e=>{if(e.target.dataset.wizardCampus){const id=e.target.dataset.wizardCampus;e.target.checked?PLAN.targetIds.add(id):PLAN.targetIds.delete(id);renderCampusPicker();document.querySelector('[data-wizard-campus="'+id+'"]')?.focus({preventScroll:true})}});
function syncMajorTiles(){const input=document.getElementById("intended-major");if(!input)return;const value=input.value.trim().toLowerCase();document.querySelectorAll("[data-major-choice]").forEach(tile=>{const selected=tile.dataset.majorChoice.toLowerCase()===value;tile.classList.toggle("selected",selected);tile.setAttribute("aria-pressed",String(selected))})}
document.addEventListener("click",e=>{if(OPEN_COURSE&&!e.target.closest("[data-course-tile]"))closeCourseDrawer();const b=e.target.closest("button");if(!b)return;if(b.dataset.workflowStep){PLAN.step=Number(b.dataset.workflowStep);PLAN.agreementStage=0;renderOnboarding(true);return}if(b.hasAttribute("data-review-dashboard")){showDashboard();return}if(b.dataset.courseToggle){const tile=b.closest("[data-course-tile]");OPEN_TILE===tile?closeCourseDrawer():openCourseDrawer(b.dataset.courseToggle,tile);return}if(b.dataset.setStatus){applyCourseStatus(b.dataset.courseId,b.dataset.setStatus);return}if(b.dataset.agreementStage!==undefined){PLAN.agreementStage=Number(b.dataset.agreementStage);renderOnboarding(true);return}if(b.hasAttribute("data-agreement-next")){PLAN.agreementStage=Math.min(agreementStages(activeAssistAgreement()).length-1,PLAN.agreementStage+1);renderOnboarding(true);return}if(b.hasAttribute("data-agreement-back")){PLAN.agreementStage=Math.max(0,PLAN.agreementStage-1);renderOnboarding(true);return}if(b.dataset.removeCampus){PLAN.targetIds.delete(b.dataset.removeCampus);renderCampusPicker()}if(b.dataset.majorChoice){document.getElementById("intended-major").value=b.dataset.majorChoice;syncMajorTiles()}const a=b.dataset.wizardAction;if(a==="back"){if(PLAN.step===3)PLAN.major=document.getElementById("intended-major").value.trim();PLAN.step=Math.max(1,PLAN.step-1);renderOnboarding(true)}if(a==="cancel-edit"){Object.assign(PLAN,PLAN.editSnapshot);PLAN.targetIds=new Set(PLAN.editSnapshot.targetIds);PLAN.editing=false;showDashboard()}});
document.addEventListener("keydown",e=>{if(e.key!=="Escape"||!OPEN_COURSE)return;const id=OPEN_COURSE;closeCourseDrawer();courseTile(id)?.querySelector(".course-pick").focus()});
renderOnboarding();
